from typing import List
def helpful_maths(nums: List[int]) ->str:
    counts = [0] * 3
    for n in nums:
        counts[n - 1] += 1
    res = []
    for i, c in enumerate(counts):
        n = str(i + 1)
        res.extend([n] * c)
    return '+'.join(res)
def solve():
    nums = list(map(int, input().rstrip().split('+')))
    print(helpful_maths(nums))
solve()

