from math import floor
from typing import List, Tuple
def parse_input() ->Tuple[int, int, List[int]]:
    n, d = [int(x) for x in input().split()]
    return n, d, [int(x) for x in input().split()]
def solve(n: int, d: int, t: List[int]) ->int:
    time = (n - 1) * 10 + sum(t)
    if time > d:
        return -1
    if time == d:
        return (n - 1) * 2
    return (n - 1) * 2 + floor((d - time) / 5)
