def helper(mat, i):
    return [row[i] for row in mat]
def solve(n, m, arr):
    s = set()
    for i in range(m):
        c = helper(arr, i)
        mx = max(c)
        for j in range(n):
            if c[j] == mx:
                s.add(j)
    return len(s)
