from math import ceil
from typing import List
def parse_input() ->List[int]:
    return [int(x) for x in input().split()]
def solve(n: int, m: int) ->int:
    if m > n:
        return -1
    k = ceil(n / 2)
    if m >= k and m <= n:
        return m
    if k % m == 0:
        return k
    return k + m - k % m
n, m = parse_input()
print(solve(n, m))

