import copy
from fractions import Fraction
def convert(number, base):
    c_num = copy.deepcopy(number)
    rest = []
    while c_num:
        rest.append(c_num % base)
        c_num //= base
    return rest
def digits_sum(numbers):
    d_sum = 0
    for number in numbers:
        d_sum += number
    return d_sum
def all_s(number):
    i = 2
    total = 0
    while i != number:
        total += digits_sum(convert(number, i))
        i += 1
    return total
def result():
    number = int(input())
    total = all_s(number)
    out = Fraction(total, number - 2)
    if total % (number - 2) != 0:
        print(out)
    else:
        print('{}/1'.format(out))
result()

