from typing import List
def solution(n: int, groups: List[int]):
    s = list(sorted(groups, reverse=True))
    taxis = 0
    while s:
        sum_ = s.pop(0)
        while s:
            x = s[-1]
            if sum_ + x <= 4:
                sum_ += s.pop(-1)
            else:
                break
        taxis += 1
    return taxis
