from typing import List
def time_diff(h1: int, m1: int, h2: int, m2: int) ->int:
    t1 = h1 * 60 + m1
    t2 = h2 * 60 + m2
    t = t2 - t1
    return t
def increas_time(h: int, m: int, t: int):
    t += h * 60 + m + 1
    return t // 60, t % 60
def solve(arr: List[List[int]], n: int, s: int):
    if arr[0] != [0, 0]:
        h1, m1 = [0, 0]
        h2, m2 = arr[0]
        diff = time_diff(h1, m1, h2, m2)
        if diff >= s + 1:
            return ' '.join(map(str, [0, 0]))
    for i in range(n - 1):
        h1, m1 = arr[i]
        h2, m2 = arr[i + 1]
        diff = time_diff(h1, m1, h2, m2)
        if diff >= 2 * s + 2:
            return ' '.join(map(str, increas_time(h1, m1, s)))
    return ' '.join(map(str, increas_time(*arr[-1], s)))
def main():
    n, s = list(map(int, input().split(' ')))
    res = []
    for _ in range(n):
        arr = list(map(int, input().split(' ')))
        res.append(arr)
    print(solve(res, n, s))
