import itertools
def get_letters(arr):
    letters = list()
    for i in arr:
        for char in i:
            if char not in letters:
                letters.append(char)
    return letters if len(letters) >= 2 else [letters[0], letters[0]]
def check_2char(word, combination):
    for i in word:
        if i not in combination:
            return False
    return True
def to_2char(arr):
    letters = get_letters(arr)
    better_option = ''
    for combination in itertools.combinations(letters, 2):
        chosen = ''
        for word in arr:
            if check_2char(word, combination):
                chosen += word
        if len(chosen) > len(better_option):
            better_option = chosen
    return len(better_option)
def main():
    n = int(input())
    arr = []
    for _ in range(n):
        arr.append(input())
    print(to_2char(arr))
main()

