from typing import *
def get_final_position(commands: str) ->int:
    pos = 0
    for ch in commands:
        if ch == '+':
            pos += 1
        else:
            pos -= 1
    return pos
def get_all_command_combinations(commands: str, combinations: Optional[List[str]]=None) ->List[str]:
    if combinations == None:
        combinations = ['']
    command = commands[0]
    result_combinations = []
    for combination in combinations:
        if command != '?':
            result_combinations.append(combination + command)
        else:
            result_combinations.append(combination + '+')
            result_combinations.append(combination + '-')
    if len(commands) == 1:
        return result_combinations
    else:
        return get_all_command_combinations(commands[1:], result_combinations)
def compute_probability(commands1: str, commands2: str) ->float:
    combinations = get_all_command_combinations(commands2)
    target_value = get_final_position(commands1)
    correct_values = 0
    for combination in combinations:
        if get_final_position(combination) == target_value:
            correct_values += 1
    return correct_values / len(combinations)
s1 = input()
s2 = input()
print(f'{compute_probability(s1, s2):.9f}')

