def fact(n):
    ans = 1
    for i in range(2, n + 1):
        ans *= i
    return ans
def solve(s1, s2):
    req = 0
    for c in s1:
        if c == '+':
            req += 1
        else:
            req -= 1
    av = 0
    t = 0
    for c in s2:
        if c == '+':
            av += 1
        elif c == '-':
            av -= 1
        else:
            t += 1
    total = 2 ** t
    dis = req - av
    if abs(dis) > t:
        return 0
    plus = 0
    minus = 0
    if dis < 0:
        minus = abs(dis)
    else:
        plus = dis
    if (t - abs(dis)) % 2 == 1:
        return 0
    plus += (t - abs(dis)) // 2
    minus += (t - abs(dis)) // 2
    desire = fact(t) / (fact(plus) * fact(minus))
    return desire / total
