def next_permutation(a):
    if len(a) < 2:
        return False
    i = len(a) - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i < 0:
        return False
    j = i + 1
    k = len(a) - 1
    while a[i] >= a[k]:
        k -= 1
    a[i], a[k] = a[k], a[i]
    a[j:] = a[:j - 1:-1]
    return True
