import functools
from fractions import Decimal
@functools.lru_cache(maxsize=None)
def bf(n, m, t):
    if t == T:
        sol.append((n + 4, m + 1))
    if n < N:
        bf(n + 1, m, t + 1)
    if m < M:
        bf(n, m + 1, t + 1)
@functools.lru_cache(maxsize=None)
def fact(n):
    if n <= 1:
        return Decimal(1)
    n = Decimal(n)
    return n * fact(n - 1)
def k_parmi_n(k, n):
    return Decimal(fact(n) / (fact(k) * fact(n - k)))
