import re
class Task:
    memory, a, b = [0] * 3
    clients = []
    answer = []
    def getData(self):
        n, self.memory = [int(x) for x in input().split(' ')]
        self.a, self.b = [int(x) for x in input().split(' ')]
        for i in range(1, n + 1):
            self.clients += [[i] + [int(x) for x in input().split(' ')]]
    def solve(self):
        self.clients.sort(key=self.clientRequiredMemory)
        for current in self.clients:
            requiredMemory = current[1] * self.a + current[2] * self.b
            if requiredMemory <= self.memory:
                self.memory -= requiredMemory
                self.answer += [current[0]]
            else:
                break
    def clientRequiredMemory(self, client):
        return client[1] * self.a + client[2] * self.b
    def printAnswer(self):
        print(len(self.answer))
        print(re.sub('[\\[\\],]', '', str(self.answer)))
