    l, r, k = (int(x) for x in input().split())
    solver(l, r, k)
def solver(l, r, k):
    getcontext().prec = 40
    dl = Decimal(l)
    dr = Decimal(r)
    dk = Decimal(k)
    raw1 = dl.ln() / dk.ln()
    if almostEqual(raw1, int(raw1)):
