def get_prices(s):
    s = list(s)
    for i, c in enumerate(s):
        if c.isalpha():
            s[i] = 'a'
    return [x for x in ''.join(s).split('a') if x]
def prices_sum(prices):
    rub = 0
    cop = 0
    for price in prices:
        if '.' in price:
            splited = price.split('.')
            if len(splited[-1]) == 2:
                cop += int(splited[-1])
                splited = splited[:-1]
            rub += int(''.join(splited))
        else:
            rub += int(price)
    rub += cop // 100
    cop %= 100
    return rub, cop
def format_rub_cop(rub, cop):
    cop_str = ''
    if cop != 0:
        cop_str = '.' + '0' * (2 - len(str(cop))) + str(cop)
    rrub = str(rub)[::-1]
    ransrub = ''
    for i in range(0, len(rrub), 3):
        ransrub += rrub[i:i + 3] + '.'
    if ransrub[-1] == '.':
        ransrub = ransrub[:-1]
    return f'{ransrub[::-1]}{cop_str}'
def main():
    s = input()
    prices = get_prices(s)
    rub, cop = prices_sum(prices)
    print(format_rub_cop(rub, cop))
