from typing import Tuple, Optional
Rect = Tuple[int, int, int, int]
def inter(r1: Rect, r2: Rect) ->Optional[Rect]:
    dx = min(r1[2], r2[2]) - max(r1[0], r2[0])
    dy = min(r1[3], r2[3]) - max(r1[1], r2[1])
    if dx >= 0 and dy >= 0:
        return max(r1[0], r2[0]), max(r1[1], r2[1]), min(r1[2], r2[2]), min(r1[3], r2[3])
    return None
def area(r: Optional[Rect]) ->int:
    return 0 if r == None else (r[2] - r[0]) * (r[3] - r[1])
