def solve():
    n, e = list(map(int, input().split()))
    enemies = [[] for _ in range(n + 1)]
    for _ in range(e):
        f, s = list(map(int, input().split()))
        enemies[f].append(s)
        enemies[s].append(f)
    def cycle_length(i, root, depth=0):
        if len(enemies[i]) == 0:
            if i == root:
                return depth
            return 0
        j = enemies[i].pop()
        if i in enemies[j]:
            enemies[j].remove(i)
        return cycle_length(j, root, depth + 1)
    ans = 0
    for i in range(1, n + 1):
        ans += cycle_length(i, i) % 2
    return ans + (n - ans) % 2
